16	export const UNITS = {
17	  rifle: {name:'Rifle squad',cost:80,hp:105,size:.45,speed:2.7,range:4.8,damage:15,trainTime:5,buildTime:5,power:0,requires:[],producer:'barracks',description:'Cheap infantry. Holds ground and screens armor; weak against vehicles.',sight:8,interval:.75,armor:'infantry'},
