20	  tank: {name:'Vanguard tank',cost:300,hp:520,size:.8,speed:2.1,range:7,damage:72,trainTime:14,buildTime:14,power:0,requires:[],producer:'factory',description:'Armored main battle tank. Crushes vehicles and defenses.',sight:9,interval:1.55,armor:'heavy'},
21	  artillery: {name:'Siege crawler',cost:380,hp:270,size:.8,speed:1.7,range:11.5,damage:115,trainTime:19,buildTime:19,power:0,requires:[],producer:'factory',description:'Long-range splash damage. Devastates buildings; protect it.',sight:9,interval:3.2,armor:'light'},
22	  harvester: {name:'Shard hauler',cost:300,hp:600,size:.8,speed:2.7,range:0,damage:0,trainTime:14,buildTime:14,power:0,requires:[],producer:'refinery',description:'Automatically collects shards and delivers 200 credits per load. Resumes after moving.',sight:8,interval:1,armor:'heavy',capacity:200},
23	  engineer: {name:'Field engineer',cost:220,hp:290,size:.7,speed:2.8,range:0,damage:0,trainTime:11,buildTime:11,power:0,requires:[],producer:'factory',description:'Unarmed maintenance vehicle. Automatically repairs nearby vehicles and structures for credits; needs power.',sight:9,interval:1,armor:'light',repairRange:4,repairRate:18},
24	  constructor: {name:'Nexus construction vehicle',cost:1800,hp:650,size:.9,speed:2,range:0,damage:0,trainTime:30,buildTime:30,power:0,requires:[],producer:'factory',description:'Unarmed mobile base. Deploy within 4 tiles to build a new nexus, opening a remote base and adding 200 unit slots when complete. Deployment consumes this vehicle at no extra cost.',sight:10,interval:1,armor:'heavy'},
25	  striker: {name:'Pike striker',cost:260,hp:320,size:.7,speed:3.5,range:6,damage:27,trainTime:12,buildTime:12,power:0,requires:[],research:'advancedBallistics',producer:'factory',description:'Fast six-wheel assault vehicle with twin autocannons. Shreds infantry; weak against heavy armor.',sight:10,interval:.55,armor:'light'},
