30	export const RACES = {
31	  organics:{name:'Organics',description:'Human and alien crews field rugged industrial armor. Reliable firepower, sturdy vehicles and fast infantry.'},
32	  aiUnity:{name:'AI Unity',description:'Costlier autonomous cohorts combine durable combat robots with agile, lighter machines and efficient infrastructure.'},
