34	const unityId=role=>`unity${role[0].toUpperCase()}${role.slice(1)}`;
35	const UNITY_BUILDINGS={
36	  core:{name:'Unity mainframe',hp:3100,power:20},reactor:{name:'Resonance spire',hp:800,power:95,description:'Armored autonomous generator. Produces 95 power for industry and defenses.'},refinery:{name:'Prism assimilator',hp:1300,power:-28,description:'Includes one automatic Prism carrier. Efficient conversion of shard deliveries into credits.'},
37	  barracks:{name:'Cohort assembler',hp:1050,description:'Prints Needle cohorts, Breach automata and Veil skimmers.'},factory:{name:'Walker forge',hp:1550,power:-38,description:'Builds articulated combat walkers, Mender drones, and Mainframe constructors.'},lab:{name:'Logic archive',hp:1000,power:-24,description:'Develops permanent combat and infrastructure algorithms. One project per archive.'},
38	  capacitor:{name:'Charge nexus',hp:800},turret:{name:'Lance node',hp:820,damage:44,interval:1.15},rocketTower:{name:'Shard battery',hp:1000,damage:80,interval:2.45},
39	  wall:{name:'Interlock barrier',hp:600},
