41	const UNITY_UNITS={
42	  rifle:{name:'Needle cohort',cost:90,hp:120,speed:2.4,damage:13,description:'Durable biped combat robots. Slower than organic infantry, with sustained pulse fire.'},
43	  rocket:{name:'Breach automaton',cost:175,hp:108,speed:2.15,damage:53,description:'Heavy biped launcher platforms. Tougher but slower than organic rocket teams.'},
44	  scout:{name:'Veil skimmer',cost:150,hp:165,speed:4.55,description:'Agile sensor machine with light armor. Wide sight and rapid anti-infantry fire.'},
45	  tank:{name:'Bastion walker',cost:325,hp:470,speed:2.4,damage:67,interval:1.5,description:'Articulated assault walker. Trades some armor and shell weight for mobility.'},
46	  artillery:{name:'Arc siege walker',cost:410,hp:235,speed:1.95,damage:110,interval:3.1,description:'Mobile long-range siege platform. Lighter armor demands careful screening.'},
47	  harvester:{name:'Prism carrier',hp:540,speed:2.7,description:'Autonomous shard carrier with a rear mineral chamber. Same cargo capacity and extraction economy as organic haulers.'},
48	  engineer:{name:'Mender drone',hp:250,speed:3.1,repairRate:18,description:'Unarmed maintenance machine. Fast relocation; repairs nearby vehicles and structures for credits and power.'},
49	  constructor:{name:'Mainframe constructor',hp:600,speed:2.2,description:'Unarmed mobile mainframe. Deploy within 4 tiles to establish a remote base and add 200 unit slots when complete. Deployment consumes this machine at no extra cost.'},
50	  striker:{name:'Talon runner',cost:280,hp:285,speed:3.85,damage:26,interval:.53,description:'Fast multi-legged hunter with paired anti-infantry pulse cannons. Vulnerable to heavy armor.'},
51	};
52	// Distinct identities share gameplay roles; faction ownership paint is independent of race.
53	for(const [role,d] of Object.entries(BUILDINGS)){
54	  if(d.race==='both'){d.role=role;continue;}
55	  Object.assign(d,{role,race:'organics'});
56	  BUILDINGS[unityId(role)]={...d,...UNITY_BUILDINGS[role],role,race:'aiUnity',requires:d.requires.map(unityId)};
57	}
58	for(const [role,d] of Object.entries(UNITS)){
59	  Object.assign(d,{role,race:'organics'});
60	  UNITS[unityId(role)]={...d,...UNITY_UNITS[role],role,race:'aiUnity',producer:unityId(d.producer),requires:d.requires.map(unityId)};
61	}
62	export function buildingRole(value){const type=typeof value==='string'?value:value?.type;return BUILDINGS[type]?.role||type;}
63	export function unitRole(value){const type=typeof value==='string'?value:value?.type;return UNITS[type]?.role||type;}
64	export function teamRace(s,team){return s.teams[team]?.race||'organics';}
65	export function raceBuilding(s,team,role){const key=buildingRole(role);return BUILDINGS[key]?.race==='both'?key:teamRace(s,team)==='aiUnity'?unityId(key):key;}
66	export function raceUnit(s,team,role){return teamRace(s,team)==='aiUnity'?unityId(unitRole(role)):unitRole(role);}
67	const entityRole=value=>buildingRole(unitRole(value));
