69	export const RESEARCH = {
70	  infantryWeapons:{name:'Pulse accelerators',branch:'Infantry',cost:220,time:30,requires:[],description:'Rifle and rocket infantry deal 18% more damage.'},
71	  infantryArmor:{name:'Composite field armor',branch:'Infantry',cost:320,time:40,requires:['infantryWeapons'],description:'Infantry gain 20% maximum health, including deployed squads.'},
