73	  mobility:{name:'Adaptive drivetrains',branch:'Vehicles',cost:350,time:40,requires:['vehicleWeapons'],description:'All vehicles, including haulers and engineers, move 15% faster.'},
74	  gridEfficiency:{name:'Efficient power routing',branch:'Infrastructure',cost:250,time:30,requires:[],description:'All structures consume 20% less electricity.'},
75	  advancedBallistics:{name:'Advanced ballistics',branch:'Infrastructure',cost:400,time:45,requires:['gridEfficiency'],description:'Unlocks the Pike striker. Rocket infantry and siege crawlers deal 10% more damage.'},
