77	export const BUILDING_UPGRADES = {
78	  speed:{name:'Accelerated operations',cost:200,time:25,types:['barracks','factory','refinery','lab'],requires:['lab'],description:'This facility trains units, researches and processes minerals 25% faster.'},
79	  efficiency:{name:'Efficient converters',cost:180,time:25,types:['refinery','barracks','factory','lab','capacitor','turret','rocketTower'],requires:['lab'],description:'This structure consumes 25% less electricity. Combines with grid research.'},
80	  advancedProduction:{name:'Advanced assembly bay',cost:260,time:35,types:['factory'],requires:['lab'],description:'This foundry can build Pike strikers after Advanced ballistics research.'},
