83	export const MAP_SIZES={
84	  standard:{name:'Standard',width:144,height:112},
85	  frontier:{name:'Frontier',width:192,height:144},
86	  vast:{name:'Vast',width:224,height:168},
87	};
88	export const MAP_PROFILES={
89	  rift:{name:'Volcanic rift',description:'Lava shores, broken ridges, and exposed rich central deposits.'},
90	  basin:{name:'Basalt basin',description:'Broad open basalt plains, sheltered expansions, and scattered mesas.'},
91	  highlands:{name:'Shattered highlands',description:'Raised plateaus, defended passes, and valuable flanking expansions.'},
92	};
93	export const MAP_WIDTH=MAP_SIZES.frontier.width,MAP_HEIGHT=MAP_SIZES.frontier.height;
94	const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
95	const sq=(x)=>x*x;
96	const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
97	const center=e=>e.kind==='building'?{x:e.x+e.size/2,y:e.y+e.size/2}:e;
98	const cell=(s,x,y)=>Math.floor(y)*s.width+Math.floor(x);
99	const inside=(s,x,y)=>x>=0&&y>=0&&x<s.width&&y<s.height;
100	const good=()=>({ok:true,reason:''});
101	const bad=reason=>({ok:false,reason});
102	const alive=e=>e.hp>0;
103	const own=(s,t,type)=>s.entities.filter(e=>alive(e)&&e.team===t&&(!type||e.type===type||entityRole(e)===type));
104	const completed=(s,t,type)=>own(s,t,type).some(e=>e.kind==='building'&&e.progress>=1);
105	const definition=e=>e.kind==='building'?BUILDINGS[e.type]:UNITS[e.type];
106	// Per-step spatial state is derived, never serialized. Ordering stays identical to entities.
107	const spatialStates=new WeakMap(),SPATIAL_CELL=6;
108	const spatialKey=e=>{const p=center(e);return `${Math.floor(p.x/SPATIAL_CELL)},${Math.floor(p.y/SPATIAL_CELL)}`;};
109	function indexEntity(s,e){
110	  const spatial=spatialStates.get(s);if(!spatial)return;
111	  const key=spatialKey(e),previous=spatial.entries.get(e.id);
112	  if(previous?.key===key)return;
113	  if(previous){const bucket=spatial.buckets.get(previous.key);bucket.splice(bucket.indexOf(previous),1);}
114	  const entry={e,key,index:previous?.index??spatial.nextIndex++};spatial.entries.set(e.id,entry);
115	  if(!spatial.buckets.has(key))spatial.buckets.set(key,[]);spatial.buckets.get(key).push(entry);
116	}
117	function beginSpatialStep(s){
118	  spatialStates.set(s,{buckets:new Map(),entries:new Map(),nextIndex:0});
119	  for(const e of s.entities)if(alive(e))indexEntity(s,e);
120	}
121	function nearbyEntities(s,p,r){
122	  const spatial=spatialStates.get(s);if(!spatial)return s.entities;
123	  const entries=[];
124	  for(let y=Math.floor((p.y-r)/SPATIAL_CELL);y<=Math.floor((p.y+r)/SPATIAL_CELL);y++)for(let x=Math.floor((p.x-r)/SPATIAL_CELL);x<=Math.floor((p.x+r)/SPATIAL_CELL);x++)for(const entry of spatial.buckets.get(`${x},${y}`)||[])entries.push(entry);
125	  return entries.sort((a,b)=>a.index-b.index).map(entry=>entry.e);
126	}
