128	export function unitRank(e){return e?.kind==='unit'?Math.min(3,Math.floor(Math.max(0,e.kills||0)/5)):0;}
129	export function unitStats(e){
130	  const d=UNITS[e?.type];if(!d)return null;
131	  const rank=unitRank(e),bonus=1+rank*.2,tech=e.tech||[],infantry=d.armor==='infantry';
132	  return{rank,hp:d.hp*bonus*(infantry&&tech.includes('infantryArmor')?1.2:1),damage:d.damage*bonus*(tech.includes(infantry?'infantryWeapons':'vehicleWeapons')?1.18:1)*(tech.includes('advancedBallistics')&&['rocket','artillery'].includes(entityRole(e))?1.1:1),speed:d.speed*bonus*(!infantry&&tech.includes('mobility')?1.15:1)};
133	}
134	
135	export function mapLayout(s){
136	  if(s.width===72&&s.height===56)return{start:{x:12,y:37},end:{x:59,y:12},bend:10};
137	  const start={x:Math.round(s.width/6),y:Math.round(s.height*.72)},end={x:s.width+1-start.x,y:s.height+1-start.y};
138	  const bend=(s.mapProfile==='basin'?12:s.mapProfile==='highlands'?9:10)*Math.min(s.width/72,s.height/56);
139	  return{start,end,bend};
140	}
