142	function random(s){let x=s.rng|0;x^=x<<13;x^=x>>>17;x^=x<<5;s.rng=x>>>0;return s.rng/4294967296;}
143	function hash(seed){let h=2166136261;for(const c of String(seed)){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return h>>>0||1;}
144	function event(s,text,team=0){s.events.push({text,team,time:s.time});}
145	export function getEntity(s,id){
146	  if(id===undefined||id===null)return undefined;
147	  const spatial=spatialStates.get(s);
148	  if(spatial){const e=spatial.entries.get(id)?.e;return e&&alive(e)?e:undefined;}
149	  return s.entities.find(e=>e.id===id&&alive(e));
150	}
151	export function unitCapacity(s,team){return Math.min(UNIT_CAP,own(s,team,'core').filter(e=>e.kind==='building'&&e.progress>=1).length*UNIT_CAP_PER_NEXUS);}
152	function reservedUnits(s,team){return own(s,team).reduce((n,e)=>n+(e.kind==='unit'?1:e.queue.length+(e.haulerPending?1:0)),0);}
153	export function powerStats(s,team){
154	  let supply=0,demand=0,reserve=0,reserveCapacity=0;
155	  for(const e of own(s,team)){
156	    if(e.kind!=='building'||e.progress<1)continue;const d=BUILDINGS[e.type],p=d.power;
157	    if(p>0)supply+=p;else demand-=p*(e.upgrades?.efficiency?.75:1);
158	    if(d.reserveCapacity){reserveCapacity+=d.reserveCapacity;reserve+=clamp(e.reserve||0,0,d.reserveCapacity);}
159	  }
160	  if(s.teams[team]?.research?.gridEfficiency)demand*=.8;
161	  const gridRatio=demand?Math.min(1,supply/demand):1,usingReserve=gridRatio<1&&reserve>1e-8,ratio=usingReserve?1:gridRatio;
162	  const surplus=Math.max(0,supply-demand),productionMultiplier=1+.25*surplus/(demand+100+surplus);
163	  return{supply,demand,gridRatio,ratio,productionMultiplier,reserve,reserveCapacity,usingReserve,status:usingReserve?'reserve':gridRatio<1?'brownout':'stable',reserveSeconds:demand>supply?reserve/(demand-supply):0};
164	}
165	
166	function advancePower(s,team,dt){
167	  const p=powerStats(s,team),capacitors=own(s,team,'capacitor').filter(e=>e.progress>=1);
168	  if(p.usingReserve){
169	    const needed=(p.demand-p.supply)*dt,used=Math.min(p.reserve,needed);let remaining=used;
170	    for(const e of capacitors){const draw=Math.min(e.reserve||0,remaining);e.reserve=(e.reserve||0)-draw;remaining-=draw;}
171	    p.ratio=Math.min(1,(p.supply+used/dt)/p.demand);
172	  }else if(p.supply>p.demand){
173	    let charge=(p.supply-p.demand)*dt;
174	    for(const e of capacitors){const amount=Math.min(BUILDINGS[e.type].reserveCapacity-(e.reserve||0),30*dt,charge);e.reserve=(e.reserve||0)+amount;charge-=amount;}
175	  }
176	  const previous=s.teams[team].powerStatus;
177	  if(previous!==p.status){s.teams[team].powerStatus=p.status;if(p.status==='brownout')event(s,'Power shortage: defenses offline; production, research and repairs slowed.',team);else if(p.status==='reserve')event(s,'Capacitor reserve engaged. Restore power before it empties.',team);else if(previous)event(s,'Power grid restored.',team);}
178	  return p;
179	}
180	
181	export function researchStatus(s,team,id){
182	  const base={completed:!!s.teams[team]?.research?.[id],queued:own(s,team,'lab').some(e=>e.research?.id===id)};
183	  const result=reason=>({...bad(reason),...base});
184	  if(!Object.hasOwn(RESEARCH,id)||![0,1].includes(team))return result('Unknown research');
185	  if(base.completed)return result('Research complete');
186	  if(base.queued)return result('Research in progress');
187	  if(s.status!=='playing')return result('Operation has ended');
188	  const missing=RESEARCH[id].requires.find(key=>!s.teams[team].research?.[key]);
189	  if(missing)return result(`Requires ${RESEARCH[missing].name}`);
190	  const labs=own(s,team,'lab').filter(e=>e.progress>=1);
191	  if(!labs.length)return result(`Requires ${BUILDINGS[raceBuilding(s,team,'lab')].name}`);
192	  if(!labs.some(e=>!e.research))return result('Laboratory is busy');
193	  if(s.teams[team].credits<RESEARCH[id].cost)return result('Insufficient credits');
194	  return{...good(),...base};
195	}
196	export function startResearch(s,team,id,labId){
197	  const result=researchStatus(s,team,id);if(!result.ok)return result;
198	  const lab=own(s,team,'lab').find(e=>e.progress>=1&&!e.research&&(labId===undefined||e.id===labId));
199	  if(!lab)return bad('Selected laboratory unavailable');
200	  s.teams[team].credits-=RESEARCH[id].cost;lab.research={id,progress:0};event(s,`${RESEARCH[id].name}: research started`,team);return{...good(),id:lab.id};
201	}
202	export function cancelResearch(s,id,team=0){
203	  const lab=getEntity(s,id);
204	  if(s.status!=='playing'||!lab||lab.team!==team||entityRole(lab)!=='lab'||!lab.research)return bad('Select your active laboratory');
205	  const refund=RESEARCH[lab.research.id].cost;s.teams[team].credits+=refund;delete lab.research;return{...good(),refund};
206	}
207	function finishResearch(s,lab){
208	  const id=lab.research.id;s.teams[lab.team].research??={};s.teams[lab.team].research[id]=true;delete lab.research;
209	  for(const e of own(s,lab.team))if(e.kind==='unit'){e.tech=Object.keys(RESEARCH).filter(key=>s.teams[e.team].research[key]);const hp=unitStats(e).hp;e.hp=Math.min(hp,e.hp+hp-e.maxHp);e.maxHp=hp;}
210	  event(s,`${RESEARCH[id].name}: research complete`,lab.team);
211	}
212	export function buildingUpgradeStatus(s,team,entityId,id){
213	  const e=getEntity(s,entityId),d=BUILDING_UPGRADES[id],base={completed:!!e?.upgrades?.[id],queued:e?.upgrade?.id===id};
214	  const result=reason=>({...bad(reason),...base});
215	  if(!Object.hasOwn(BUILDING_UPGRADES,id)||!e||e.kind!=='building'||e.team!==team)return result('Select your structure');
216	  if(!d.types.includes(entityRole(e)))return result('Upgrade unavailable for this structure');
217	  if(base.completed)return result('Upgrade complete');if(base.queued)return result('Upgrade in progress');
218	  if(s.status!=='playing')return result('Operation has ended');
219	  if(e.progress<1)return result('Finish construction first');
220	  if(e.upgrade)return result('Structure upgrade in progress');
221	  const missing=d.requires.find(key=>!completed(s,team,key));if(missing)return result(`Requires ${BUILDINGS[raceBuilding(s,team,missing)].name}`);
222	  if(s.teams[team].credits<d.cost)return result('Insufficient credits');
223	  return{...good(),...base};
224	}
225	export function startBuildingUpgrade(s,team,entityId,id){
226	  const result=buildingUpgradeStatus(s,team,entityId,id);if(!result.ok)return result;
227	  s.teams[team].credits-=BUILDING_UPGRADES[id].cost;getEntity(s,entityId).upgrade={id,progress:0};event(s,`${BUILDING_UPGRADES[id].name}: upgrade started`,team);return good();
228	}
