230	function addEntity(s,team,kind,type,x,y,built=true){
231	  const d=kind==='building'?BUILDINGS[type]:UNITS[type];
232	  const e={id:s.nextId++,team,kind,type,x,y,hp:built?d.hp:d.hp*.2,maxHp:d.hp,size:d.size,angle:team?Math.PI:0,progress:built?1:0,cooldown:random(s),order:{type:'idle'},path:[],repath:0};
233	  if(kind==='unit'){e.kills=0;e.tech=Object.keys(RESEARCH).filter(key=>s.teams[team].research?.[key]);e.hp=e.maxHp=unitStats(e).hp;}
234	  const role=entityRole(type);
235	  if(role==='capacitor')e.reserve=0;
