646	    const cx=Math.floor(p.x/2),cy=Math.floor(p.y/2);
647	    for(let yy=cy-1;yy<=cy+1;yy++)for(let xx=cx-1;xx<=cx+1;xx++)for(const e of occupied.get(`${xx},${yy}`)||[])if(sq(p.x-e.x)+sq(p.y-e.y)<=sq((size+e.size)*.43+.18))return false;
