651	  // Keep precise single-unit clicks when free; groups reserve distinct cells so A* cannot merge them.
652	  if(units.length===1&&region&&region===s.regions[cell(s,units[0].x,units[0].y)]&&free({x,y},units[0].size))return new Map([[units[0].id,{x,y}]]);
653	  const candidates=[];
654	  for(let i=0;i<s.blocked.length;i++)if(!s.blocked[i]&&groups.has(s.regions[i])&&s.regions[i])candidates.push(i);
655	  const score=i=>sq(i%s.width+.5-x)+sq(Math.floor(i/s.width)+.5-y);
656	  candidates.sort((a,b)=>score(a)-score(b)||a-b);
