674	    }
675	    return assigned;
676	  }
677	  while(remaining.length&&slots.length){
678	    let best=Infinity,unit=-1,slot=-1;
679	    for(let i=0;i<remaining.length;i++)for(let j=0;j<slots.length;j++)if(slots[j].region===s.regions[cell(s,remaining[i].x,remaining[i].y)]){
680	      const d=sq(remaining[i].x-slots[j].x)+sq(remaining[i].y-slots[j].y);if(d<best){best=d;unit=i;slot=j;}
681	    }
682	    if(unit<0)break;
