    if(u.trafficWait>=.8-1e-8){u.passUntil=s.time+1.5;u.trafficWait=0;}
  }
}

function aiBuild(s,team,type,near){
  type=raceBuilding(s,team,type);
  const {width:W,height:H}=s;
