        for (const a of [0, Math.PI / 2, Math.PI, Math.PI * 1.5]) line(ctx, p.x + Math.cos(a) * (r + 3), p.y + Math.sin(a) * (r + 3) * .65, p.x + Math.cos(a) * (r + 7), p.y + Math.sin(a) * (r + 7) * .65, color);
