export function drawIcon(canvas, type, team = 0, state = {}) {
  if (!canvas) return;
  const bounds = canvas.getBoundingClientRect();
  const w = bounds.width || 76, h = bounds.height || 64;
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
