  const scale = BUILDINGS.has(type) ? Math.min(w / (size * 40 + 8), h / (size * 38 + 15)) : Math.min(w / 50, h / 43);
  ctx.scale(scale, scale);
  const entity = { ...state, type, team, size, progress: state.progress ?? 1, angle: -.35, cargo: state.cargo ?? 0 };
