// Capture baseline screenshots of Ashline: menu, early base, mid-game battle.
const { chromium } = await import('/Users/vojta/Dev/evangelist-exchange/node_modules/playwright/index.mjs');
const out = process.env.OUT || 'REDACTED';
const url = process.env.ASHLINE_URL || 'http://127.0.0.1:8000/fun/ashline/';
