await page.screenshot({ path: `${out}/01-menu.png` });
await page.locator('#seed').fill('BASELINE-01');
await page.locator('#deploy').click();
await page.waitForFunction(() => ashline.state && !ashline.loading && !ashline.paused, null, { timeout: 120000 });
await page.waitForTimeout(800);
await page.screenshot({ path: `${out}/02-start.png` });
// Fast-forward the sim with both sides AI-driven for a mid-game look.
await page.evaluate(async () => {
  const s = ashline.state;
  s.aiTeams = [0, 1];
  s.aiByTeam = { 0: { nextThink: 0, nextRaid: 100, known: {}, mode: '', scoutIndex: 0, buildIndex: 0, raid: 0 } };
});
const mod = await page.evaluate(async () => {
  const sim = await import('./sim.js');
  const s = ashline.state;
  for (let i = 0; i < 360 * 4; i++) sim.updateGame(s, .25);
  s.fogClock = 1e9; s.visible[0].fill(1); s.explored[0].fill(1);
  return { time: s.time, entities: s.entities.length, status: s.status };
});
console.log(JSON.stringify(mod));
await page.waitForTimeout(500);
await page.screenshot({ path: `${out}/03-mid-base.png` });
// Find a fight: center camera on the centroid of units closest to each other across teams.
const fight = await page.evaluate(() => {
  const s = ashline.state; let best = null, d = Infinity;
  const u0 = s.entities.filter(e => e.team === 0 && e.kind === 'unit'), u1 = s.entities.filter(e => e.team === 1 && e.kind === 'unit');
  for (const a of u0) for (const b of u1) { const dd = Math.hypot(a.x - b.x, a.y - b.y); if (dd < d) { d = dd; best = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 }; } }
  return best;
