234	function hopperLevel(entity) {
235	  let fill = Math.max(0, Number(buildingRole(entity) === 'refinery' ? entity.processingAmount : entity.cargo) || 0) / (UNITS[entity.type]?.capacity || UNITS.harvester.capacity);
236	  if (unitRole(entity) === 'harvester' && entity.unloadDepotId != null) fill *= Math.max(0, 1 - (entity.unload || 0) / 1.2);
237	  // Only an actually full load gets the full image; the first shards are already visible.
238	  return fill <= 0 ? 0 : fill >= .999 ? 4 : Math.max(1, Math.min(3, Math.round(fill * 4)));
239	}
240	
241	function splitSheet(image, columns, rows, size, keyed, anchored = false, recolor = true, indices = null) {
242	  const cellWidth = image.width / columns, cellHeight = image.height / rows;
243	  const cells = [];
244	  for (const index of indices || Array.from({ length: columns * rows }, (_, i) => i)) {
245	    const row = Math.floor(index / columns), column = index % columns;
246	    const source = canvas(Math.ceil(cellWidth), Math.ceil(cellHeight));
247	    const ctx = source.getContext('2d', { willReadFrequently: true });
248	    ctx.drawImage(image, column * cellWidth, row * cellHeight, cellWidth, cellHeight, 0, 0, source.width, source.height);
249	    const pixels = ctx.getImageData(0, 0, source.width, source.height);
250	    if (keyed) { removeMatte(pixels); ctx.putImageData(pixels, 0, 0); }
251	    const box = bounds(pixels, !anchored);
252	    if (!anchored) { box.cx = box.left + box.width / 2; box.cy = box.top + box.height / 2; }
253	    cells.push({ source, box });
254	  }
255	  // Recenter each source pose on the same output body anchor; animation shares one scale.
256	  const maxDimension = Math.max(...cells.map(({ box }) => Math.max(box.width, box.height)));
257	  const maxRadius = Math.max(...cells.map(({ box: b }) => Math.max(b.cx - b.left, b.left + b.width - b.cx, b.cy - b.top, b.top + b.height - b.cy)));
258	  return cells.map(({ source, box }) => {
259	    const dimension = anchored ? maxDimension : Math.max(box.width, box.height);
260	    const scale = (size - 8) / (anchored ? maxRadius * 2 : dimension);
261	    const prepared = canvas(size), ctx = prepared.getContext('2d');
262	    // Prepare enough detail for high-density displays without drawing full atlases per frame.
263	    ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = 'high';
264	    ctx.drawImage(source, box.left, box.top, box.width, box.height,
265	      size / 2 + (box.left - box.cx) * scale, size / 2 + (box.top - box.cy) * scale,
266	      box.width * scale, box.height * scale);
267	    const friendly = recolor ? factionFrame(prepared, 0) : prepared;
268	    return { teams: recolor ? [friendly, factionFrame(friendly, 1)] : [prepared],
269	      side: anchored ? silhouette(prepared, '#344147') : null,
270	      shadow: silhouette(prepared, '#0b1117', size * .021),
271	      contact: silhouette(prepared, '#080f14', size * .008),
272	      drawScale: size / (dimension * scale), coverage: box.width * box.height / (source.width * source.height) };
273	  });
274	}
