276	async function load(name, prepare) {
277	  try {
278	    const image = new Image();
279	    image.src = new URL(`./assets/generated/${name}.webp`, import.meta.url).href;
280	    await image.decode();
281	    // Image decoding can finish together. Serialize CPU work with a paint between atlases.
282	    const prepared = preparation.then(async () => { await nextPaint(); await prepare(image); assetStatus.loaded++; });
283	    preparation = prepared.catch(() => {});
284	    await prepared;
285	  } catch (error) {
286	    assetStatus.errors.push(`${name}: ${error.message}`);
287	  }
288	}
