// One group per entity; replacing a group leaves unrelated assignments intact.
export function assignControlGroup(game, ids, group, team = 0) {
  if (!Number.isInteger(group) || group < 1 || group > 5) return [];
  const selected = new Set(ids);
  const assigned = [];
  for (const entity of game.entities) {
    if (entity.team !== team || entity.hp <= 0) continue;
    if (entity.controlGroup === group) delete entity.controlGroup;
    if (selected.has(entity.id)) {
      entity.controlGroup = group;
      assigned.push(entity.id);
    }
  }
  return assigned;
}

export function controlGroupMembers(game, group, team = 0) {
  if (!Number.isInteger(group) || group < 1 || group > 5) return [];
  return game.entities.filter(entity => entity.team === team && entity.hp > 0 && entity.controlGroup === group).map(entity => entity.id);
}
// Five native-resolution steps shared by mouse, touch, keyboard and save restoration.
export function zoomLevels(nativeZoom) {
  return [.5, .625, .75, .875, 1].map(scale => nativeZoom * scale);
}

export function nearestZoom(value, levels) {
  return levels.reduce((best, level) => Math.abs(level - value) < Math.abs(best - value) ? level : best);
}

export function steppedZoom(value, direction, levels) {
  const index = levels.indexOf(nearestZoom(value, levels));
  return levels[Math.max(0, Math.min(levels.length - 1, index + Math.sign(direction)))];
}

export function cameraDirection(keys, pointer, width, height) {
  let x = Number(keys.has('d') || keys.has('arrowright')) - Number(keys.has('a') || keys.has('arrowleft'));
  let y = Number(keys.has('s') || keys.has('arrowdown')) - Number(keys.has('w') || keys.has('arrowup'));
  if (pointer) {
    const edge = (coordinate, extent) => coordinate < 22 ? -Math.min(1, (22 - coordinate) / 14) : coordinate > extent - 22 ? Math.min(1, (coordinate - extent + 22) / 14) : 0;
    x = Math.max(-1, Math.min(1, x + edge(pointer.x, width)));
    y = Math.max(-1, Math.min(1, y + edge(pointer.y, height)));
  }
  const magnitude = Math.max(1, Math.hypot(x, y));
  return { x: x / magnitude, y: y / magnitude };
}
const schedulePaint = globalThis.requestAnimationFrame?.bind(globalThis);

// A timer after animation-frame callbacks lets the browser paint before the next CPU slice.
export function nextPaint() {
  return new Promise(resolve => schedulePaint(() => setTimeout(resolve, 0)));
}

export function generateOperation(seed, difficulty, options) {
  return new Promise((resolve, reject) => {
    const worker = new Worker(new URL('./world-worker.js', import.meta.url), { type: 'module' });
    worker.onmessage = ({ data }) => {
      worker.terminate();
      if (data.error) reject(new Error(data.error));
      else resolve(data.game);
    };
    worker.onerror = event => { event.preventDefault(); worker.terminate(); reject(new Error('The sector could not be generated. Please try again.')); };
    worker.postMessage({ seed, difficulty, options });
  });
}
// Seed generation never occupies the menu/loading screen's main thread.
import { createGame } from './sim.js';
self.onmessage = ({ data: { seed, difficulty, options } }) => {
  try { self.postMessage({ game: createGame(seed, difficulty, options) }); }
  catch (error) { self.postMessage({ error: error.message }); }
};

