const { chromium } = await import('/Users/vojta/Dev/evangelist-exchange/node_modules/playwright/index.mjs');
import { mkdir } from 'node:fs/promises';
const url = process.env.URL || 'http://127.0.0.1:8120/fun/ashline/';
const out = process.env.OUT || 'REDACTED';
await mkdir(out, { recursive: true });
const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1600, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto(url);
await page.waitForFunction(() => window.ashline?.booted);
await page.screenshot({ path: `${out}/01-menu.png` });
await page.locator('#seed').fill('TOUR-01');
await page.locator('#deploy').click();
await page.waitForFunction(() => ashline.state && !ashline.loading && !ashline.paused, null, { timeout: 120000 });
await page.waitForTimeout(1500);
await page.screenshot({ path: `${out}/02-start.png` });
const info = await page.evaluate(async (secs) => {
  const sim = await import('./sim.js');
  const s = ashline.state;
  s.aiTeams = [0, 1];
  s.aiByTeam = { 0: JSON.parse(JSON.stringify(s.ai)) };
  s.aiByTeam[0].nextThink = 0;
  for (let i = 0; i < secs * 4; i++) { sim.updateGame(s, .25); if (s.status !== 'playing') break; }
  return { time: s.time, n: s.entities.length, status: s.status, rules: s.rules };
}, Number(process.env.SECS || 480));
console.log(JSON.stringify(info));
await page.waitForTimeout(1200);
await page.screenshot({ path: `${out}/03-base.png` });
const spots = await page.evaluate(() => {
  const s = ashline.state; let best = null, d = Infinity;
  const u0 = s.entities.filter(e => e.team === 0 && e.kind === 'unit'), u1 = s.entities.filter(e => e.team === 1 && e.kind === 'unit');
  for (const a of u0) for (const b of u1) { const dd = Math.hypot(a.x - b.x, a.y - b.y); if (dd < d) { d = dd; best = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 }; } }
  return best;
});
if (spots) {
  await page.evaluate(p => { ashline.view.x = p.x; ashline.view.y = p.y; }, spots);
  // let the real loop run a few seconds so effects are live
  await page.waitForTimeout(2500);
  await page.screenshot({ path: `${out}/04-fight.png` });
}
await page.keyboard.press('Escape');
await page.waitForTimeout(600);
await page.screenshot({ path: `${out}/05-pause.png` });
console.log('errors', JSON.stringify(errors.slice(0, 10)));
await browser.close();
